"use client";

import { cn } from "@/lib/utils";
import { useCallback, useEffect, useRef, useState } from "react";

interface ScratchCardProps {
  /** Content revealed after scratching */
  children: React.ReactNode;
  /** Width of the card */
  width?: number;
  /** Height of the card */
  height?: number;
  /** Brush radius for scratching */
  brushSize?: number;
  /** Percentage of area scratched to trigger full reveal (0-100) */
  revealThreshold?: number;
  /** Callback when card is fully revealed */
  onReveal?: () => void;
  /** Callback with current scratch percentage */
  onScratchProgress?: (percentage: number) => void;
  /** Overlay color or gradient preset */
  overlay?: "silver" | "gold" | "holographic" | "dark";
  /** Additional CSS classes */
  className?: string;
  /** Border radius in pixels */
  borderRadius?: number;
  /** Particle intensity multiplier (0 = off, 1 = normal, 2 = intense) */
  particleIntensity?: number;
}

// ─── Overlay configs ───

const OVERLAY_CONFIGS = {
  silver: {
    gradient: [
      { offset: 0, color: "#e8e8e8" },
      { offset: 0.2, color: "#d4d4d8" },
      { offset: 0.4, color: "#c0c0c0" },
      { offset: 0.6, color: "#b8b8bc" },
      { offset: 0.8, color: "#d1d1d6" },
      { offset: 1, color: "#a8a8ad" },
    ],
    noiseOpacity: 0.12,
    shineColor: "rgba(255, 255, 255, 0.25)",
    particleColors: ["#e8e8e8", "#c0c0c0", "#d4d4d8", "#ffffff", "#a8a8ad", "#b0b0b5"],
    glowColor: "rgba(255, 255, 255, 0.6)",
  },
  gold: {
    gradient: [
      { offset: 0, color: "#f5e6a3" },
      { offset: 0.2, color: "#e6c84d" },
      { offset: 0.4, color: "#d4a84b" },
      { offset: 0.6, color: "#e8d068" },
      { offset: 0.8, color: "#c9a84c" },
      { offset: 1, color: "#b8942a" },
    ],
    noiseOpacity: 0.1,
    shineColor: "rgba(255, 248, 220, 0.3)",
    particleColors: ["#f5e6a3", "#e6c84d", "#ffd700", "#fff8dc", "#d4a84b", "#c9a84c"],
    glowColor: "rgba(255, 215, 0, 0.5)",
  },
  holographic: {
    gradient: [
      { offset: 0, color: "#c4b5fd" },
      { offset: 0.15, color: "#93c5fd" },
      { offset: 0.3, color: "#6ee7b7" },
      { offset: 0.5, color: "#fde68a" },
      { offset: 0.65, color: "#fca5a5" },
      { offset: 0.8, color: "#c4b5fd" },
      { offset: 1, color: "#93c5fd" },
    ],
    noiseOpacity: 0.08,
    shineColor: "rgba(255, 255, 255, 0.35)",
    particleColors: ["#c4b5fd", "#93c5fd", "#6ee7b7", "#fde68a", "#fca5a5", "#f0abfc"],
    glowColor: "rgba(196, 181, 253, 0.5)",
  },
  dark: {
    gradient: [
      { offset: 0, color: "#2a2a2e" },
      { offset: 0.2, color: "#3a3a3f" },
      { offset: 0.4, color: "#28282d" },
      { offset: 0.6, color: "#3d3d42" },
      { offset: 0.8, color: "#2f2f34" },
      { offset: 1, color: "#1f1f24" },
    ],
    noiseOpacity: 0.15,
    shineColor: "rgba(255, 255, 255, 0.08)",
    particleColors: ["#5a5a5f", "#4a4a4f", "#6a6a6f", "#8a8a8f", "#3a3a3f", "#7a7a7f"],
    glowColor: "rgba(150, 150, 160, 0.4)",
  },
};

type OverlayConfig = (typeof OVERLAY_CONFIGS)[keyof typeof OVERLAY_CONFIGS];

// Padding around the card where particles can fly into
const PARTICLE_OVERFLOW = 80;

// ─── Particle system ───

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  rotation: number;
  rotationSpeed: number;
  angularDrag: number;
  color: string;
  shape: "shard" | "spark" | "dust" | "flake";
  shimmerPhase: number;
  shimmerSpeed: number;
  gravity: number;
  drag: number;
  // For sparks: trail history
  trail: { x: number; y: number }[];
}

function pickColor(config: OverlayConfig): string {
  return config.particleColors[
    Math.floor(Math.random() * config.particleColors.length)
  ]!;
}

/**
 * Spawn a particle at (x,y) that flies AWAY from the scratch.
 *
 * scratchVx/Vy = the mouse/finger velocity.
 * Particles are ejected perpendicular to the scratch direction
 * (like debris being scraped off a coin edge) with some spread,
 * plus a component opposite to scratch direction (material pushed aside).
 */
function createParticle(
  x: number,
  y: number,
  scratchVx: number,
  scratchVy: number,
  scratchSpeed: number,
  brushRadius: number,
  config: OverlayConfig
): Particle {
  // Perpendicular direction (normal to scratch)
  const scratchAngle = Math.atan2(scratchVy, scratchVx);
  // Randomly pick one side of the perpendicular
  const side = Math.random() > 0.5 ? 1 : -1;
  const perpAngle = scratchAngle + (Math.PI / 2) * side;

  // Eject angle: mostly perpendicular, with some spread
  const spread = (Math.random() - 0.5) * 1.8; // ±0.9 radians
  const ejectAngle = perpAngle + spread;

  // Spawn at the brush EDGE, not center
  const edgeOffset = brushRadius * (0.4 + Math.random() * 0.6);
  const spawnAngle = ejectAngle + (Math.random() - 0.5) * 0.5;
  const sx = x + Math.cos(spawnAngle) * edgeOffset;
  const sy = y + Math.sin(spawnAngle) * edgeOffset;

  // Energy scales with scratch speed
  const energy = Math.min(scratchSpeed, 40); // cap so it doesn't go insane

  // Pick shape with weighted probability
  const roll = Math.random();
  let shape: Particle["shape"];
  if (roll < 0.15) shape = "spark";
  else if (roll < 0.45) shape = "shard";
  else if (roll < 0.75) shape = "flake";
  else shape = "dust";

  let size: number;
  let maxLife: number;
  let gravity: number;
  let drag: number;
  let ejectSpeed: number;
  let angularDrag: number;

  switch (shape) {
    case "spark":
      // Fast, tiny, bright, short-lived — like a coin scratch spark
      size = 1 + Math.random() * 1.5;
      maxLife = 15 + Math.random() * 15;
      gravity = 0.02;
      drag = 0.94;
      ejectSpeed = (3 + energy * 0.4) * (0.8 + Math.random() * 0.4);
      angularDrag = 1;
      break;
    case "shard":
      // Heavy metallic chunks — fall fast, tumble
      size = 2.5 + Math.random() * 4;
      maxLife = 25 + Math.random() * 20;
      gravity = 0.35 + Math.random() * 0.15; // heavy!
      drag = 0.96;
      ejectSpeed = (1.5 + energy * 0.2) * (0.6 + Math.random() * 0.8);
      angularDrag = 0.98;
      break;
    case "flake":
      // Thin curled pieces — flutter down like leaf/peel
      size = 2 + Math.random() * 3.5;
      maxLife = 40 + Math.random() * 30;
      gravity = 0.08 + Math.random() * 0.06;
      drag = 0.97;
      ejectSpeed = (2 + energy * 0.25) * (0.5 + Math.random() * 0.5);
      angularDrag = 0.96;
      break;
    case "dust":
      // Fine motes — float, drift with air turbulence
      size = 0.5 + Math.random() * 1.2;
      maxLife = 50 + Math.random() * 40;
      gravity = 0.01 + Math.random() * 0.02;
      drag = 0.99;
      ejectSpeed = (0.5 + energy * 0.1) * (0.3 + Math.random() * 0.7);
      angularDrag = 0.99;
      break;
  }

  return {
    x: sx,
    y: sy,
    vx: Math.cos(ejectAngle) * ejectSpeed,
    vy: Math.sin(ejectAngle) * ejectSpeed - (shape === "spark" ? 1.5 : 0.5), // slight upward bias
    life: maxLife,
    maxLife,
    size,
    rotation: Math.random() * Math.PI * 2,
    rotationSpeed: (Math.random() - 0.5) * 0.6,
    angularDrag,
    color: pickColor(config),
    shape,
    shimmerPhase: Math.random() * Math.PI * 2,
    shimmerSpeed: 0.15 + Math.random() * 0.25,
    gravity,
    drag,
    trail: [],
  };
}

function updateParticle(p: Particle): boolean {
  p.life--;
  if (p.life <= 0) return false;

  // Store trail for sparks
  if (p.shape === "spark" && p.trail.length < 6) {
    p.trail.push({ x: p.x, y: p.y });
  } else if (p.shape === "spark") {
    p.trail.shift();
    p.trail.push({ x: p.x, y: p.y });
  }

  // Apply drag
  p.vx *= p.drag;
  p.vy *= p.drag;

  // Apply gravity (per-particle — shards fall fast, dust floats)
  p.vy += p.gravity;

  // Air turbulence for dust and flakes
  if (p.shape === "dust") {
    p.vx += (Math.random() - 0.5) * 0.25;
    p.vy += (Math.random() - 0.5) * 0.15;
  } else if (p.shape === "flake") {
    // Flutter: sinusoidal horizontal drift
    p.vx += Math.sin(p.shimmerPhase * 3) * 0.12;
    p.vy += (Math.random() - 0.5) * 0.05;
  }

  // Move
  p.x += p.vx;
  p.y += p.vy;

  // Rotation with drag (shards slow their tumble over time)
  p.rotationSpeed *= p.angularDrag;
  p.rotation += p.rotationSpeed;

  // Shimmer
  p.shimmerPhase += p.shimmerSpeed;

  return true;
}

function drawParticle(
  ctx: CanvasRenderingContext2D,
  p: Particle,
  glowColor: string
) {
  const lifeRatio = p.life / p.maxLife;
  // Ease-out fade
  const alpha = lifeRatio < 0.3 ? lifeRatio / 0.3 : 1;
  // Fade-in (first 3 frames)
  const fadeIn = Math.min(1, (p.maxLife - p.life) / 3);
  const finalAlpha = alpha * fadeIn;
  if (finalAlpha <= 0.01) return;

  const shimmer = 0.5 + Math.sin(p.shimmerPhase) * 0.5;

  ctx.save();
  ctx.globalAlpha = finalAlpha;

  switch (p.shape) {
    case "spark": {
      // Draw trail first
      if (p.trail.length > 1) {
        ctx.beginPath();
        ctx.moveTo(p.trail[0]!.x, p.trail[0]!.y);
        for (let i = 1; i < p.trail.length; i++) {
          ctx.lineTo(p.trail[i]!.x, p.trail[i]!.y);
        }
        ctx.lineTo(p.x, p.y);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size * 0.5;
        ctx.globalAlpha = finalAlpha * 0.3;
        ctx.stroke();
        ctx.globalAlpha = finalAlpha;
      }

      // Bright core
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = 8 * shimmer;
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.5 + shimmer * 0.5), 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      break;
    }

    case "shard": {
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);

      // Irregular polygon shard
      const s = p.size;
      ctx.beginPath();
      ctx.moveTo(-s * 0.2, -s);
      ctx.lineTo(s * 0.6, -s * 0.3);
      ctx.lineTo(s * 0.4, s * 0.8);
      ctx.lineTo(-s * 0.5, s * 0.4);
      ctx.closePath();

      // Fill with slight gradient feel
      ctx.fillStyle = p.color;
      ctx.fill();

      // Specular edge highlight
      ctx.strokeStyle = `rgba(255,255,255,${0.3 + shimmer * 0.3})`;
      ctx.lineWidth = 0.6;
      ctx.stroke();

      // Tiny inner highlight for 3D
      ctx.globalAlpha = finalAlpha * shimmer * 0.4;
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.ellipse(s * 0.1, -s * 0.1, s * 0.2, s * 0.15, p.rotation * 0.5, 0, Math.PI * 2);
      ctx.fill();
      break;
    }

    case "flake": {
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);

      // 3D perspective squash — flake tumbles so it appears to rotate in 3D
      const squash = 0.2 + Math.abs(Math.cos(p.rotation * 1.5)) * 0.8;
      ctx.scale(1, squash);

      // Thin ellipse
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Curved highlight to sell the curl
      ctx.globalAlpha = finalAlpha * 0.5 * shimmer;
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.ellipse(
        -p.size * 0.15,
        -p.size * 0.05,
        p.size * 0.35,
        p.size * 0.15,
        -0.3,
        0,
        Math.PI * 2
      );
      ctx.fill();
      break;
    }

    case "dust": {
      // Simple soft dot
      const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size);
      g.addColorStop(0, p.color);
      g.addColorStop(1, "transparent");
      ctx.fillStyle = g;
      ctx.globalAlpha = finalAlpha * 0.6;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
  }

  ctx.restore();
}

// ─── Overlay drawing ───

function drawOverlay(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  config: OverlayConfig,
  borderRadius: number
) {
  ctx.save();

  if (borderRadius > 0) {
    ctx.beginPath();
    ctx.roundRect(0, 0, width, height, borderRadius);
    ctx.clip();
  }

  const baseGradient = ctx.createLinearGradient(0, 0, width, height);
  for (const stop of config.gradient) {
    baseGradient.addColorStop(stop.offset, stop.color);
  }
  ctx.fillStyle = baseGradient;
  ctx.fillRect(0, 0, width, height);

  // Shine band
  const shineGradient = ctx.createLinearGradient(0, 0, width, 0);
  shineGradient.addColorStop(0, "transparent");
  shineGradient.addColorStop(0.3, "transparent");
  shineGradient.addColorStop(0.5, config.shineColor);
  shineGradient.addColorStop(0.7, "transparent");
  shineGradient.addColorStop(1, "transparent");
  ctx.fillStyle = shineGradient;
  ctx.fillRect(0, 0, width, height);

  // Noise grain
  const noiseCanvas = document.createElement("canvas");
  noiseCanvas.width = width;
  noiseCanvas.height = height;
  const noiseCtx = noiseCanvas.getContext("2d")!;
  const imageData = noiseCtx.createImageData(width, height);
  const d = imageData.data;
  for (let i = 0; i < d.length; i += 4) {
    const v = Math.random() * 255;
    d[i] = v;
    d[i + 1] = v;
    d[i + 2] = v;
    d[i + 3] = config.noiseOpacity * 255;
  }
  noiseCtx.putImageData(imageData, 0, 0);
  ctx.drawImage(noiseCanvas, 0, 0);

  // Brushed metal lines
  ctx.globalAlpha = 0.04;
  for (let y = 0; y < height; y += 2) {
    ctx.strokeStyle = y % 4 === 0 ? "#fff" : "#000";
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(0, y + Math.random() * 0.5);
    ctx.lineTo(width, y + Math.random() * 0.5);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // "SCRATCH HERE" text
  ctx.globalCompositeOperation = "source-over";
  const fontSize = Math.min(width, height) * 0.06;
  ctx.font = `600 ${fontSize}px -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = "rgba(0, 0, 0, 0.15)";
  ctx.fillText("SCRATCH HERE", width / 2, height / 2 + 1.5);
  ctx.fillStyle = "rgba(255, 255, 255, 0.55)";
  ctx.fillText("SCRATCH HERE", width / 2, height / 2);

  // Inner border
  ctx.strokeStyle = "rgba(255, 255, 255, 0.12)";
  ctx.lineWidth = 1;
  if (borderRadius > 0) {
    ctx.beginPath();
    ctx.roundRect(1, 1, width - 2, height - 2, borderRadius - 1);
    ctx.stroke();
  } else {
    ctx.strokeRect(1, 1, width - 2, height - 2);
  }

  ctx.restore();
}

// ─── Brush erase ───

function drawBrush(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number
) {
  ctx.globalCompositeOperation = "destination-out";

  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
  gradient.addColorStop(0, "rgba(0,0,0,1)");
  gradient.addColorStop(0.6, "rgba(0,0,0,0.95)");
  gradient.addColorStop(0.85, "rgba(0,0,0,0.4)");
  gradient.addColorStop(1, "rgba(0,0,0,0)");

  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();

  // Rough edge spatter
  const dots = 3 + Math.floor(Math.random() * 4);
  for (let i = 0; i < dots; i++) {
    const a = Math.random() * Math.PI * 2;
    const d = radius * (0.6 + Math.random() * 0.5);
    const r = 1 + Math.random() * 2.5;
    ctx.beginPath();
    ctx.arc(x + Math.cos(a) * d, y + Math.sin(a) * d, r, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ─── Component ───

export function ScratchCard({
  children,
  width = 360,
  height = 200,
  brushSize = 30,
  revealThreshold = 55,
  onReveal,
  onScratchProgress,
  overlay = "silver",
  className,
  borderRadius = 16,
  particleIntensity = 1,
}: ScratchCardProps) {
  const scratchCanvasRef = useRef<HTMLCanvasElement>(null);
  const particleCanvasRef = useRef<HTMLCanvasElement>(null);
  const isDrawingRef = useRef(false);
  const lastPointRef = useRef<{ x: number; y: number } | null>(null);
  const [isRevealed, setIsRevealed] = useState(false);
  const hasRevealedRef = useRef(false);
  const particlesRef = useRef<Particle[]>([]);
  const particleRafRef = useRef<number | null>(null);
  const calcRafRef = useRef<number | null>(null);

  const config = OVERLAY_CONFIGS[overlay];

  // The particle canvas is larger than the card — it has PARTICLE_OVERFLOW px of padding
  // on each side so particles can fly outside the card bounds.
  const pCanvasW = width + PARTICLE_OVERFLOW * 2;
  const pCanvasH = height + PARTICLE_OVERFLOW * 2;

  // ─── Init scratch canvas ───
  useEffect(() => {
    const canvas = scratchCanvasRef.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    const ctx = canvas.getContext("2d", { willReadFrequently: true })!;
    ctx.scale(dpr, dpr);
    drawOverlay(ctx, width, height, config, borderRadius);
  }, [width, height, config, borderRadius]);

  // ─── Init particle canvas ───
  useEffect(() => {
    const canvas = particleCanvasRef.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = pCanvasW * dpr;
    canvas.height = pCanvasH * dpr;
  }, [pCanvasW, pCanvasH]);

  // ─── Particle animation loop ───
  useEffect(() => {
    const canvas = particleCanvasRef.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    const ctx = canvas.getContext("2d")!;
    let running = true;

    function tick() {
      if (!running) return;
      ctx.clearRect(0, 0, canvas!.width, canvas!.height);
      ctx.save();
      ctx.scale(dpr, dpr);

      // Particle coordinates are in card-space.
      // Offset by PARTICLE_OVERFLOW so (0,0) in card-space
      // maps to (PARTICLE_OVERFLOW, PARTICLE_OVERFLOW) on the particle canvas.
      ctx.translate(PARTICLE_OVERFLOW, PARTICLE_OVERFLOW);

      const alive: Particle[] = [];
      for (const p of particlesRef.current) {
        if (updateParticle(p)) {
          // Cull if way off screen
          if (
            p.x > -PARTICLE_OVERFLOW &&
            p.x < pCanvasW &&
            p.y > -PARTICLE_OVERFLOW &&
            p.y < pCanvasH
          ) {
            drawParticle(ctx, p, config.glowColor);
          }
          alive.push(p);
        }
      }
      particlesRef.current = alive;

      ctx.restore();
      particleRafRef.current = requestAnimationFrame(tick);
    }

    tick();
    return () => {
      running = false;
      if (particleRafRef.current) cancelAnimationFrame(particleRafRef.current);
    };
  }, [config.glowColor, pCanvasW, pCanvasH]);

  // ─── Scratch percentage ───
  const calculateScratchPercentage = useCallback(() => {
    const canvas = scratchCanvasRef.current;
    if (!canvas) return 0;
    const ctx = canvas.getContext("2d", { willReadFrequently: true })!;
    const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imgData.data;
    let transparent = 0;
    // Sample every 4th pixel for perf
    for (let i = 3; i < data.length; i += 16) {
      if (data[i]! < 128) transparent++;
    }
    return (transparent / (data.length / 16)) * 100;
  }, []);

  // ─── Spawn particles ───
  const spawnParticles = useCallback(
    (x: number, y: number, vx: number, vy: number) => {
      if (particleIntensity <= 0) return;

      const speed = Math.sqrt(vx * vx + vy * vy);
      // Scale count with speed: slow scratch = few particles, fast = shower
      const count = Math.floor(
        Math.max(2, (2 + speed * 0.6) * particleIntensity)
      );

      for (let i = 0; i < count; i++) {
        particlesRef.current.push(
          createParticle(x, y, vx, vy, speed, brushSize, config)
        );
      }

      // Hard cap
      if (particlesRef.current.length > 800) {
        particlesRef.current = particlesRef.current.slice(-500);
      }
    },
    [brushSize, config, particleIntensity]
  );

  // ─── Handle scratch ───
  const handleScratch = useCallback(
    (clientX: number, clientY: number) => {
      const canvas = scratchCanvasRef.current;
      if (!canvas || isRevealed) return;

      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const ctx = canvas.getContext("2d", { willReadFrequently: true })!;

      let vx = 0;
      let vy = 0;

      if (lastPointRef.current) {
        vx = x - lastPointRef.current.x;
        vy = y - lastPointRef.current.y;
        const dist = Math.sqrt(vx * vx + vy * vy);

        if (dist < 0.5) {
          // Barely moved — just erase in place, no particles
          drawBrush(ctx, x, y, brushSize);
          lastPointRef.current = { x, y };
          return;
        }

        // Interpolate erase brush along stroke
        const eraseSteps = Math.max(1, Math.floor(dist / (brushSize * 0.3)));
        for (let i = 0; i <= eraseSteps; i++) {
          const t = i / eraseSteps;
          drawBrush(
            ctx,
            lastPointRef.current.x + vx * t,
            lastPointRef.current.y + vy * t,
            brushSize
          );
        }

        // Spawn particles along the stroke (every ~6px)
        const pSteps = Math.max(1, Math.floor(dist / 6));
        for (let i = 0; i <= pSteps; i++) {
          const t = i / pSteps;
          spawnParticles(
            lastPointRef.current.x + vx * t,
            lastPointRef.current.y + vy * t,
            vx,
            vy
          );
        }
      } else {
        drawBrush(ctx, x, y, brushSize);
        // Initial touch — small burst in random directions
        for (let i = 0; i < Math.ceil(3 * particleIntensity); i++) {
          const a = Math.random() * Math.PI * 2;
          particlesRef.current.push(
            createParticle(x, y, Math.cos(a) * 2, Math.sin(a) * 2, 2, brushSize, config)
          );
        }
      }

      lastPointRef.current = { x, y };

      // Throttled percentage check
      if (calcRafRef.current) cancelAnimationFrame(calcRafRef.current);
      calcRafRef.current = requestAnimationFrame(() => {
        const pct = calculateScratchPercentage();
        onScratchProgress?.(pct);

        if (pct >= revealThreshold && !hasRevealedRef.current) {
          hasRevealedRef.current = true;
          // Celebration burst — particles from all over the card
          for (let i = 0; i < Math.ceil(50 * particleIntensity); i++) {
            const bx = Math.random() * width;
            const by = Math.random() * height;
            const ba = Math.random() * Math.PI * 2;
            particlesRef.current.push(
              createParticle(bx, by, Math.cos(ba) * 4, Math.sin(ba) * 4 - 2, 4, brushSize, config)
            );
          }
          setIsRevealed(true);
          onReveal?.();
        }
      });
    },
    [
      brushSize,
      isRevealed,
      revealThreshold,
      calculateScratchPercentage,
      onReveal,
      onScratchProgress,
      spawnParticles,
      particleIntensity,
      width,
      height,
      config,
    ]
  );

  // ─── Input handlers ───

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      isDrawingRef.current = true;
      lastPointRef.current = null;
      handleScratch(e.clientX, e.clientY);
    },
    [handleScratch]
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (!isDrawingRef.current) return;
      handleScratch(e.clientX, e.clientY);
    },
    [handleScratch]
  );

  const handleMouseUp = useCallback(() => {
    isDrawingRef.current = false;
    lastPointRef.current = null;
  }, []);

  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      e.preventDefault();
      isDrawingRef.current = true;
      lastPointRef.current = null;
      const touch = e.touches[0];
      if (!touch) return;
      handleScratch(touch.clientX, touch.clientY);
    },
    [handleScratch]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      e.preventDefault();
      if (!isDrawingRef.current) return;
      const touch = e.touches[0];
      if (!touch) return;
      handleScratch(touch.clientX, touch.clientY);
    },
    [handleScratch]
  );

  const handleTouchEnd = useCallback(() => {
    isDrawingRef.current = false;
    lastPointRef.current = null;
  }, []);

  // Cleanup
  useEffect(() => {
    return () => {
      if (calcRafRef.current) cancelAnimationFrame(calcRafRef.current);
    };
  }, []);

  // Global up listeners
  useEffect(() => {
    const up = () => {
      isDrawingRef.current = false;
      lastPointRef.current = null;
    };
    window.addEventListener("mouseup", up);
    window.addEventListener("touchend", up);
    return () => {
      window.removeEventListener("mouseup", up);
      window.removeEventListener("touchend", up);
    };
  }, []);

  return (
    <div
      className={cn("relative inline-block select-none", className)}
      style={{ width, height, borderRadius }}
    >
      {/* Content layer */}
      <div className="absolute inset-0 overflow-hidden" style={{ borderRadius }}>
        <div className="flex h-full w-full items-center justify-center">
          {children}
        </div>
      </div>

      {/* Scratch overlay canvas */}
      <canvas
        ref={scratchCanvasRef}
        className={cn(
          "absolute inset-0 touch-none transition-opacity duration-700",
          isRevealed && "pointer-events-none opacity-0"
        )}
        style={{
          width,
          height,
          borderRadius,
          cursor: isRevealed ? "default" : "grab",
        }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      />

      {/*
        Particle canvas — LARGER than the card by PARTICLE_OVERFLOW on each side.
        Positioned with negative offset so it extends beyond card bounds.
        pointer-events: none so it doesn't block scratching.
        overflow: visible so particles aren't clipped.
      */}
      <canvas
        ref={particleCanvasRef}
        className="pointer-events-none absolute"
        style={{
          width: pCanvasW,
          height: pCanvasH,
          top: -PARTICLE_OVERFLOW,
          left: -PARTICLE_OVERFLOW,
        }}
      />

      {/* Premium shadow overlay */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          borderRadius,
          boxShadow: `
            inset 0 1px 0 rgba(255,255,255,0.1),
            inset 0 -1px 0 rgba(0,0,0,0.1),
            0 2px 8px rgba(0,0,0,0.12),
            0 8px 24px rgba(0,0,0,0.08)
          `,
        }}
      />
    </div>
  );
}
